fn binary_search_recursive(v: &[i32], elem: i32, c: isize, f: isize) -> isize {
    // If the current interval [c..=f] is empty, return the last valid position c-1
    if c > f {
        return c - 1;
    }
    // Compute mid, avoiding overflow
    let mid = c + (f - c) / 2;
    let mid_usize = mid as usize;

    if v[mid_usize] <= elem {
        // The last position ≤ elem must be in [mid+1..=f], if it exists
        binary_search_recursive(v, elem, mid + 1, f)
    } else {
        // Otherwise it must be in [c..=mid-1]
        binary_search_recursive(v, elem, c, mid - 1)
    }
}

